/* Enceinte connectée (option model) : photo détourée + calques animés.
   Amazon Echo (Pop, Dot, Show 5 / 8 / 10 / 11 / 15, Spot), Google Nest (Mini, Audio, Hub, Hub 2e gén., Hub Max),
   Sonos (One, One SL, Era 100, Era 300, Beam, Sub Mini, Sub).
   Calques : ondes sonores (vitesse suivant le volume), anneau / arc lumineux (Echo Pop, Dot), écran
   (reflet qui balaie, lueur, égaliseur ; vitre sombre éteint), 4 points Google (Nest Mini, Audio),
   voyant blanc et « pompe » des basses (Sonos). Coordonnées des calques en pixels de la photo d'origine. */
const SPK_IMG = {
  echo_pop: "data:image/webp;base64,",
  echo_dot: "data:image/webp;base64,",
  echo_show_5: "data:image/webp;base64,",
  echo_show_8: "data:image/webp;base64,",
  echo_show_10: "data:image/webp;base64,",
  echo_show_11: "data:image/webp;base64,",
  echo_show_15: "data:image/webp;base64,",
  echo_spot: "data:image/webp;base64,",
  nest_mini: "data:image/webp;base64,",
  nest_audio: "data:image/webp;base64,",
  nest_hub: "data:image/webp;base64,",
  nest_hub_2: "data:image/webp;base64,",
  nest_hub_max: "data:image/webp;base64,",
  sonos_one: "data:image/webp;base64,",
  sonos_one_sl: "data:image/webp;base64,",
  sonos_era_100: "data:image/webp;base64,",
  sonos_era_300: "data:image/webp;base64,",
  sonos_beam: "data:image/webp;base64,",
  sonos_sub_mini: "data:image/webp;base64,",
  sonos_sub: "data:image/webp;base64,",
};
// w, h : taille de la photo ; led : anneau [cx, cy, rx, ry, rotation] ; scr : coins de l'écran TL, TR, BR, BL ;
// circ : écran rond [cx, cy, rx, ry] ; dots : points Google [x0, x1, y, r] ; sled : voyant Sonos [cx, cy] ; bass : 1 enceinte, 2 caisson
const SPK_GEO = {
  echo_pop: { w: 266, h: 257, led: [133, 10.3, 69, 12.9, -20] },
  echo_dot: { w: 303, h: 286, led: [154.5, 266, 115, 11.4, 0] },
  echo_show_5: { w: 344, h: 246, scr: [[47, 57], [279, 40], [257, 203], [22, 195]] },
  echo_show_8: { w: 376, h: 278, scr: [[54, 47], [322, 31], [295, 225], [24, 228]] },
  echo_show_10: { w: 378, h: 316, scr: [[75, 28], [351, 48], [361, 233], [80, 233]] },
  echo_show_11: { w: 384, h: 282, scr: [[55, 42], [348, 25], [320, 250], [20, 240]] },
  echo_show_15: { w: 452, h: 278, scr: [[45, 41], [414, 34], [414, 235], [32, 234]] },
  echo_spot: { w: 237, h: 249, circ: [101.9, 117, 90, 102] },
  nest_mini: { w: 198, h: 222, dots: [76.4, 120.8, 119.4, 3.6] },
  nest_audio: { w: 184, h: 253, dots: [62, 103, 130, 3.1] },
  nest_hub: { w: 288, h: 198, scr: [[30, 29], [262, 20], [261, 161], [19, 165]] },
  nest_hub_2: { w: 333, h: 223, scr: [[31, 37], [308, 22], [289, 197], [20, 195]] },
  nest_hub_max: { w: 341, h: 260, scr: [[52, 37], [314, 22], [307, 232], [20, 227]] },
  sonos_one: { w: 142, h: 192, sled: [71, 6.7], bass: 1 },
  sonos_one_sl: { w: 138, h: 192, sled: [69, 6.7], bass: 1 },
  sonos_era_100: { w: 137, h: 182, sled: [68.5, 5.5], bass: 1 },
  sonos_era_300: { w: 230, h: 183, bass: 1 },
  sonos_beam: { w: 492, h: 90, sled: [246, 27], bass: 1 },
  sonos_sub_mini: { w: 112, h: 182, bass: 2 },
  sonos_sub: { w: 167, h: 193, bass: 2 },
};
const SPK_MODELS = Object.keys(SPK_GEO);
// modèle : option model (ou style), sinon deviné depuis l'entité (sonos / nest / google), sinon Echo Dot
function spkModel(c) {
  const raw = String((c && (c.model || c.style)) || "").toLowerCase().replace(/[\s-]+/g, "_");
  if (SPK_GEO[raw]) return raw;
  if (SPK_GEO[`echo_${raw}`]) return `echo_${raw}`;
  const e = String((c && c.entity) || "").toLowerCase();
  return /sonos/.test(e) ? "sonos_one" : /nest|google|home_mini|chromecast/.test(e) ? "nest_mini" : "echo_dot";
}
const spkBrand = (md) => md.split("_")[0];
SVG.smart_speaker = (c) => {
  const md = spkModel(c), g = SPK_GEO[md], br = spkBrand(md);
  // photo posée en bas de la zone 112 × 124, centrée
  const s = Math.min(112 / g.w, 124 / g.h), W = g.w * s, H = g.h * s, x0 = 60 - W / 2, y0 = 134 - H;
  const f = (n) => +n.toFixed(2);
  const cx = 60, cy = f(y0 + H / 2), wide = g.w / g.h > 3;
  const r = f(Math.max(W, H) * (wide ? 0.42 : 0.4));
  const waves = [0, 1, 2].map((i) => wide
    ? `<ellipse cx="${cx}" cy="${cy}" rx="${r}" ry="${f(r / 3)}" style="animation-delay:${i * 0.5}s"/>`
    : `<circle cx="${cx}" cy="${cy}" r="${r}" style="animation-delay:${i * 0.5}s"/>`).join("");
  let over = "", defs = "";
  // matrice qui envoie le carré unité sur l'écran (coins TL, TR, BL) : égaliseur et barres suivent la perspective
  const eq = (TL, TR, BL, u0, v1, n, du) => {
    const m = [TR[0] - TL[0], TR[1] - TL[1], BL[0] - TL[0], BL[1] - TL[1], TL[0], TL[1]].map(f).join(" ");
    const bars = Array.from({ length: n }, (_, i) => `<rect x="${f(u0 + i * du)}" y="${f(v1 - 0.16)}" width="${f(du * 0.55)}" height="0.16" rx="0.004"/>`).join("");
    return `<g class="sp-eq" transform="matrix(${m})">${bars}</g>`;
  };
  if (g.scr || g.circ) {
    let shape, TL, TR, BL, bx, by, bw, bh;
    if (g.scr) {
      shape = `<polygon points="${g.scr.map((p) => p.join(",")).join(" ")}"/>`;
      [TL, TR, , BL] = g.scr;
      const xs = g.scr.map((p) => p[0]), ys = g.scr.map((p) => p[1]);
      bx = Math.min(...xs); by = Math.min(...ys); bw = Math.max(...xs) - bx; bh = Math.max(...ys) - by;
    } else {
      const [ex, ey, rx, ry] = g.circ;
      shape = `<ellipse cx="${ex}" cy="${ey}" rx="${rx}" ry="${ry}"/>`;
      TL = [ex - rx, ey - ry]; TR = [ex + rx, ey - ry]; BL = [ex - rx, ey + ry];
      bx = ex - rx; by = ey - ry; bw = 2 * rx; bh = 2 * ry;
    }
    defs += `<clipPath id="ID-scr">${shape}</clipPath>
<linearGradient id="ID-sweep" x1="0" y1="0" x2="1" y2=".35"><stop offset=".38" stop-color="#fff" stop-opacity="0"/><stop offset=".5" stop-color="#fff" stop-opacity=".32"/><stop offset=".62" stop-color="#fff" stop-opacity="0"/></linearGradient>`;
    over += `<g clip-path="url(#ID-scr)"><g class="sp-scr">
<rect class="sp-glow" x="${bx}" y="${by}" width="${bw}" height="${bh}"/>
<rect class="sp-sweep" x="${bx}" y="${by}" width="${bw}" height="${bh}" fill="url(#ID-sweep)"/>
${g.scr ? eq(TL, TR, BL, 0.83, 0.92, 5, 0.026) : eq(TL, TR, BL, 0.43, 0.8, 3, 0.05)}
<rect class="sp-glass" x="${bx}" y="${by}" width="${bw}" height="${bh}"/>
</g></g>`;
  }
  if (g.led) {
    const [lx, ly, rx, ry, rot] = g.led;
    defs += `<radialGradient id="ID-led"><stop offset="0" stop-color="#bdf0ff"/><stop offset=".55" style="stop-color:var(--sp-led)"/><stop offset="1" style="stop-color:var(--sp-led)" stop-opacity="0"/></radialGradient>`;
    over += `<ellipse class="sp-led" cx="${lx}" cy="${ly}" rx="${rx}" ry="${ry}" fill="url(#ID-led)" transform="rotate(${rot} ${lx} ${ly})"/>`;
  }
  if (g.dots) {
    const [d0, d1, dy, dr] = g.dots;
    over += `<g class="sp-dots">${[0, 1, 2, 3].map((i) => `<circle cx="${f(d0 + (d1 - d0) * i / 3)}" cy="${dy}" r="${dr}" style="animation-delay:${(i * 0.18).toFixed(2)}s"/>`).join("")}</g>`;
  }
  if (g.sled) over += `<circle class="sp-sled" cx="${g.sled[0]}" cy="${g.sled[1]}" r="${f(Math.max(3, g.w / 40))}"/>`;
  return `<defs>${DEFS}${defs}</defs>
<g class="spk spk-${br} m-${md}${g.bass ? ` sp-bass${g.bass === 2 ? " sp-sub" : ""}` : ""}">
<ellipse cx="60" cy="135" rx="${f(Math.min(50, W * 0.42))}" ry="3" fill="url(#ID-shadow)"/>
<g class="sp-waves">${waves}</g>
<g class="sp-pump"><g transform="translate(${f(x0)} ${f(y0)}) scale(${+s.toFixed(4)})">
<image class="sp-photo" href="${SPK_IMG[md]}" width="${g.w}" height="${g.h}" preserveAspectRatio="none"/>
${over}
</g></g>
</g>`;
};
